(()=>{'use strict';
const equipment=document.body.dataset.siteKind==='equipment';
const $=s=>document.querySelector(s),frame=$('#preview'),sections={services:'خدمات',steps:'مراحل سفارش',gallery:'تصویر و ایده',guides:'راهنماها',faq:'پرسش‌های متداول',about:'دربارهٔ لابراتوار',contact:'ارتباط'},imageNames={hero:'تصویر اصلی',print:'تصویر کارت چاپ',paper:'تصویر کارت کاغذ',gallery:'تصویر بخش ایده‌ها'};
let defaultImages={hero:'/lab-site/print-studio.webp',print:'/lab-site/print-detail.webp',paper:'/lab-site/print-studio.webp',gallery:'/lab-site/print-wall.webp'};
const errors={forbidden:'دسترسی مدیر لابراتوار لازم است. از پنل لابراتوار وارد شوید.',invalid_origin:'نشانی صفحه معتبر نیست.',site_revision_conflict:'نسخهٔ سایت در پنجرهٔ دیگری تغییر کرده است. تغییرات شما نگه داشته شد؛ پیش از ذخیره، نسخهٔ تازه را بازخوانی و مقایسه کنید.',invalid_site_collection:'اطلاعات کارت‌ها یا پرسش‌ها معتبر نیست؛ هر کارت حداکثر ۵ تصویر دارد.',site_images_too_large:'مجموع تصاویر کارت‌ها زیاد است؛ عکس‌ها را کوچک‌تر کنید.',invalid_site_text:'یکی از نوشته‌ها بیش از اندازه طولانی یا نامعتبر است.',site_title_required:'نام سایت و عنوان اصلی نمی‌توانند خالی باشند.',invalid_site_phone:'شمارهٔ تماس معتبر وارد کنید.',invalid_site_image:'عکس معتبر JPEG، PNG یا WebP انتخاب کنید.',site_image_too_large:'حجم تصویر زیاد است؛ تصویر کوچک‌تری انتخاب کنید.'};
if(equipment)errors.forbidden='دسترسی مدیر فروشگاه لازم است. از پنل فروشگاه وارد شوید.';
let state,config,snapshot,dirty=false,saving=false,imageKey='',previewReady=false;
const clone=x=>JSON.parse(JSON.stringify(x));
const notice=s=>{$('#notice').textContent=s;};
async function api(options){const res=await fetch(equipment?'/api/rental/site':'/api/lab/site',{credentials:'same-origin',...options,headers:{'content-type':'application/json'}}),body=await res.json();if(!res.ok)throw new Error(errors[body.error]||'دریافت یا ذخیرهٔ سایت انجام نشد. دوباره تلاش کنید.');return body;}
function mark(){dirty=true;$('#saveState').textContent='تغییرات ذخیره‌نشده';$('#save').disabled=saving;$('#undo').disabled=saving;}
function theme(){const doc=frame.contentDocument;if(!doc)return;const root=doc.documentElement;for(const key of ['primary','background','ink'])root.style.setProperty(key==='background'?'--page-bg':'--'+key,config[key]);root.style.setProperty('--site-font',config.font);root.style.setProperty('--site-size',config.fontSize+'px');}
function apply(){if(!config||!previewReady)return;const doc=frame.contentDocument;if(equipment)window.PBEquipmentCollections?.render(doc,config,{mark,chooseImage});for(const el of doc.querySelectorAll('[data-site-field]')){const key=el.dataset.siteField;if(doc.activeElement!==el&&typeof config[key]==='string')el.textContent=config[key];}for(const el of doc.querySelectorAll('[data-site-image]')){const src=config.images[el.dataset.siteImage];if(src&&el.getAttribute('src')!==src)el.src=src;}for(const key of equipment?[]:config.sections){const el=doc.querySelector('[data-site-section="'+key+'"]');if(el){el.hidden=config.hidden.includes(key);doc.querySelector('main').append(el);}}theme();}
function renderSections(){const root=$('#sections');root.replaceChildren();if(equipment){for(const [path,label]of [['/','خانه'],['/equipment','خدمات تجهیزات'],['/guides','راهنمای تجهیزات'],['/order-guide','راهنمای سفارش'],['/faq','پرسش‌های متداول'],['/about','دربارهٔ فروشگاه'],['/contact','ارتباط']]){const button=document.createElement('button');button.type='button';button.className='jump';button.textContent=label;button.onclick=()=>{previewReady=false;frame.src='/rental/site-preview?page='+encodeURIComponent(path);};root.append(button);}return;}config.sections.forEach((key,index)=>{const row=document.createElement('div');row.className='section-control';const top=document.createElement('div'),label=document.createElement('label'),check=document.createElement('input');check.type='checkbox';check.checked=!config.hidden.includes(key);check.onchange=()=>{config.hidden=config.hidden.filter(k=>k!==key);if(!check.checked)config.hidden.push(key);apply();mark();};label.append(check,document.createTextNode(sections[key]));top.append(label);for(const [text,offset]of [['↑',-1],['↓',1]]){const button=document.createElement('button');button.textContent=text;button.setAttribute('aria-label',(offset<0?'بالا بردن ':'پایین بردن ')+sections[key]);button.disabled=index+offset<0||index+offset>=config.sections.length;button.onclick=()=>{[config.sections[index],config.sections[index+offset]]=[config.sections[index+offset],config.sections[index]];renderSections();apply();mark();};top.append(button);}const jump=document.createElement('button');jump.className='jump';jump.textContent='رفتن به بخش';jump.onclick=()=>{if(config.hidden.includes(key))notice('این بخش پنهان است؛ برای ویرایش ابتدا آن را فعال کنید.');else frame.contentDocument.querySelector('[data-site-section="'+key+'"]')?.scrollIntoView({behavior:'smooth',block:'start'});};row.append(top,jump);root.append(row);});}
function syncControls(){for(const [id,key]of [['primaryColor','primary'],['backgroundColor','background'],['inkColor','ink'],['font','font'],['fontSize','fontSize']])$('#'+id).value=config[key];document.querySelectorAll('[data-config]').forEach(el=>el.value=config[el.dataset.config]||'');renderSections();}
function makeEditable(){if(!config||!frame.contentDocument)return;previewReady=true;const doc=frame.contentDocument;let style=doc.getElementById('site-edit-outlines');if(!style){style=doc.createElement('style');style.id='site-edit-outlines';style.textContent='[data-site-field]{cursor:text;outline:1px dashed transparent;outline-offset:4px;min-width:12px}[data-site-field]:hover,[data-site-field]:focus{outline-color:#315efb;background:#315efb08;border-radius:3px}[data-site-image]{cursor:pointer;outline:2px dashed transparent;outline-offset:-5px}[data-site-image]:hover,[data-site-image]:focus{outline-color:#315efb}.contact-details>div:has(.empty-field:empty){display:block}.empty-field:empty{display:block!important;min-height:25px}.empty-field:empty:before{content:attr(data-placeholder);color:#97a2b5;font-size:12px}[hidden]{display:none!important}';doc.head.append(style);}for(const el of doc.querySelectorAll('[data-site-field]')){el.contentEditable='plaintext-only';el.spellcheck=false;el.title='کلیک کنید و متن را تغییر دهید';el.oninput=()=>{config[el.dataset.siteField]=el.textContent;for(const other of doc.querySelectorAll('[data-site-field="'+el.dataset.siteField+'"]'))if(other!==el)other.textContent=el.textContent;const input=document.querySelector('[data-config="'+el.dataset.siteField+'"]');if(input)input.value=el.textContent;mark();};el.onpaste=e=>{e.preventDefault();doc.execCommand('insertText',false,e.clipboardData.getData('text/plain'));};}for(const el of doc.querySelectorAll('[data-site-image]')){el.tabIndex=0;el.setAttribute('role','button');el.setAttribute('aria-label','تغییر '+imageNames[el.dataset.siteImage]);el.onclick=()=>chooseImage(el.dataset.siteImage);el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();chooseImage(el.dataset.siteImage);}};}doc.addEventListener('click',e=>{const link=e.target.closest('a');if(link)e.preventDefault();});apply();}
function chooseImage(key){imageKey=key;$('#imageInput').multiple=typeof key==='object'&&key.index===undefined;$('#imageInput').click();}
$('#imageInput').onchange=async e=>{const files=[...e.target.files],target=imageKey;e.target.value='';if(!files.length)return;const card=typeof target==='object'?config.serviceCards.find(x=>x.id===target.cardId):null;if(typeof target==='object'&&!card)return;if(card&&target.index===undefined&&card.images.length+files.length>5){notice('هر کارت حداکثر ۵ تصویر می‌تواند داشته باشد.');return;}try{const images=[];for(const file of files){if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>12000000)throw Error('یک تصویر JPEG، PNG یا WebP با حجم کمتر از ۱۲ مگابایت انتخاب کنید.');const url=URL.createObjectURL(file);try{const image=new Image();image.src=url;await image.decode();const scale=Math.min(1,1400/Math.max(image.naturalWidth,image.naturalHeight)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.naturalWidth*scale));canvas.height=Math.max(1,Math.round(image.naturalHeight*scale));canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);let data=canvas.toDataURL('image/webp',.8);if(data.length>500000)data=canvas.toDataURL('image/webp',.6);if(data.length>580000)throw Error('تصویر جزئیات زیادی دارد؛ تصویر کوچک‌تری انتخاب کنید.');images.push(data);}finally{URL.revokeObjectURL(url);}}if(card){if(target.index===undefined)card.images.push(...images);else card.images[target.index]=images[0];}else config.images[target]=images[0];apply();mark();notice('تصویر در پیش‌نمایش تغییر کرد؛ برای نمایش عمومی، ذخیره و انتشار را بزنید.');}catch(e){notice(e.message||'تصویر باز نشد. عکس دیگری انتخاب کنید.');}};
for(const [id,key]of [['primaryColor','primary'],['backgroundColor','background'],['inkColor','ink'],['font','font'],['fontSize','fontSize']])$('#'+id).oninput=e=>{if(!config)return;config[key]=key==='fontSize'?Number(e.target.value):e.target.value;theme();mark();};
document.querySelectorAll('[data-config]').forEach(el=>el.oninput=()=>{config[el.dataset.config]=el.value;apply();mark();});
$('#save').onclick=async()=>{if(!dirty||saving)return;saving=true;$('#save').disabled=true;$('#undo').disabled=true;$('#save').textContent='در حال ذخیره…';notice('');try{const result=await api({method:'PUT',body:JSON.stringify({config,revision:state.revision})});state.revision=result.revision;config=result.config;snapshot=clone(config);dirty=false;$('#saveState').textContent='ذخیره شد و روی سایت اعمال شد';syncControls();apply();notice('تغییرات صفحهٔ اصلی ذخیره شد. سایت عمومی در بازدید بعدی نسخهٔ تازه را نمایش می‌دهد.');}catch(e){notice(e.message);}finally{saving=false;$('#save').disabled=!dirty;$('#undo').disabled=!dirty;$('#save').textContent='ذخیره و انتشار';}};
$('#undo').onclick=()=>{if(dirty&&!confirm('تغییرات ذخیره‌نشده کنار گذاشته شوند؟'))return;config=clone(snapshot);dirty=false;syncControls();apply();$('#save').disabled=true;$('#undo').disabled=true;$('#saveState').textContent='نسخهٔ ذخیره‌شده';notice('');};
function viewport(mobile){const stage=$('#stage');frame.style.width=(mobile?390:Math.max(760,stage.clientWidth-40))+'px';$('#mobile').classList.toggle('active',mobile);$('#desktop').classList.toggle('active',!mobile);$('#mobile').setAttribute('aria-pressed',String(mobile));$('#desktop').setAttribute('aria-pressed',String(!mobile));}
$('#mobile').onclick=()=>viewport(true);$('#desktop').onclick=()=>viewport(false);addEventListener('resize',()=>viewport($('#mobile').classList.contains('active')));
frame.addEventListener('load',makeEditable);addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
(async()=>{try{state=await api();if(state.defaultImages)defaultImages=state.defaultImages;if(equipment){imageNames.logo='لوگوی فروشگاه';const sectionDetails=$('#sections').closest('details');sectionDetails.querySelector('summary').textContent='صفحات سایت';sectionDetails.querySelector('p').textContent='هر صفحه را جداگانه باز کنید و نوشته‌ها و عکس‌های همان صفحه را تغییر دهید.';sections.about='دربارهٔ فروشگاه';imageNames.print='تصویر تجهیزات';imageNames.paper='تصویر کیت پروژه';errors.forbidden='دسترسی مدیر فروشگاه لازم است.';}config=state.config;snapshot=clone(config);$('#labName').textContent=(state.shop||state.lab).name;const domains=$('#domains');if(!state.domains.length)domains.textContent='دامنه‌ای متصل نیست. طراحی و ذخیرهٔ سایت قبل از اتصال دامنه هم ممکن است.';for(const d of state.domains){const link=document.createElement('a');link.href='https://'+d.hostname;link.target='_blank';link.rel='noopener noreferrer';link.textContent=d.hostname+(d.active?' · مشاهدهٔ سایت':' · اتصال تکمیل نشده');domains.append(link);}for(const [key,label]of Object.entries(imageNames)){const row=document.createElement('div');row.className='image-control';const name=document.createElement('span');name.textContent=label;const button=document.createElement('button');button.textContent='تغییر عکس';button.onclick=()=>chooseImage(key);const reset=document.createElement('button');reset.textContent='عکس اولیه';reset.onclick=()=>{config.images[key]=defaultImages[key];apply();mark();};row.append(name,button,reset);$('#imageControls').append(row);}syncControls();$('#saveState').textContent='روی متن یا عکس کلیک کنید';if(frame.contentDocument?.readyState==='complete')makeEditable();viewport(innerWidth<760);}catch(e){notice(e.message);$('#saveState').textContent='دریافت انجام نشد';}})();
})();
